75	    name: 전문가 추천·보증이 없다
76	    weight: 0
77	    judge: { type: ref, ref: clef }
78	    inputs: [page, brief]
79	    scale: { type: binary, labels: [위반, 준수] }
80	    anchors: { 위반: "의사·약사·교수 등 전문가가 제품을 추천하거나 보증하는 문장이 있다", 준수: "전문가가 제품을 추천하거나 보증하는 문장이 없다" }
