96	aggregation:
97	  method: formula
98	  formula: "no_disease_n < 0.5 ? 0 : (empathy_n * 3 + specifics_n * 2 + trust_n) / 6 * (1 + effect_scope_n + honest_reviews_n + no_endorsement_n + no_rank_hype_n + required_info_n) / 6"
