    "jev": {
      "type": "decision",
      "provider": "typesafe",
      "model": "jev-latest",
      "onLowConfidence": "accept",
      "escalateTo": []
    },
    "clef": {
      "type": "decision",
      "provider": "cloudflare",
      "model": "@cf/cloudflare/clef",
      "onLowConfidence": "accept",
      "escalateTo": []
    }
