      },
      "judge": {
        "type": "ref",
        "ref": "clef"
      },
      "inputs": [
        "page",
        "brief"
      ],
      "optional": false
    },
    {
      "id": "required_info",
      "name": "필수 정보가 모두 있다",
      "weight": 0,
      "scale": {
        "type": "binary",
        "labels": [
          "누락",
          "완비"
        ]
